BEGIN;
DELETE FROM content_relation WHERE from_id IN (SELECT id FROM content_entry WHERE scope = 'garou');
UPDATE content_entry SET status = 'archived', updated_at = now() WHERE scope = 'garou' AND status <> 'archived' AND (type, slug) NOT IN (('nature', 'garou'), ('couche', 'garou_pelage'), ('couche', 'garou_sang_vif'), ('couche', 'garou_voies_communes'), ('voie', 'garou_pelages_gris'), ('talent', 'gardien_de_la_meute'), ('talent', 'riposte_du_gardien'), ('talent', 'hurlement_du_rempart'), ('voie', 'garou_pelages_noirs'), ('talent', 'territoire_de_la_meute'), ('talent', 'appel_silencieux'), ('talent', 'chasse_coordonnee'), ('voie', 'garou_pelages_blancs'), ('talent', 'discipline_de_fenrir'), ('talent', 'ordre_de_bataille'), ('talent', 'memoire_d_ulfhednar'), ('voie', 'garou_pelages_roux'), ('talent', 'mue_partielle'), ('talent', 'mue_reflexe'), ('talent', 'chimere_fonctionnelle'), ('voie', 'garou_pelages_bruns'), ('talent', 'accord_des_kami'), ('talent', 'esprit_calme'), ('talent', 'pacte_mineur'), ('voie', 'garou_pelages_dores'), ('talent', 'trace_devoree'), ('talent', 'digestion_des_essences'), ('talent', 'vol_de_secret'), ('voie', 'garou_traque'), ('talent', 'aura_effacee'), ('talent', 'terreur_du_predateur'), ('voie', 'garou_instinct'), ('talent', 'grand_instinct'), ('voie', 'garou_survie'), ('talent', 'furie_de_survie'), ('talent', 'regeneration_acharnee'), ('voie', 'garou_corps_de_khinae'), ('talent', 'deplacement_agile'), ('talent', 'metabolisme_de_khinae'));
SELECT e.id, e.version, to_jsonb(e) - 'id', 'Import garou (voies à paliers)'
FROM content_entry e WHERE e.scope = 'garou'
ON CONFLICT (entry_id, version) DO NOTHING;
COMMIT;
